import{_ as a}from"./chunks/prontera-compare4.n1BRComL.js";import{_ as d,o as r,c as e,ag as o}from"./chunks/framework.DGzMGr_a.js";const p=JSON.parse('{"title":"装备制作与精炼指南","description":"RO3 装备制作、精炼、附魔系统全方位攻略","frontmatter":{"title":"装备制作与精炼指南","description":"RO3 装备制作、精炼、附魔系统全方位攻略","lastUpdated":true},"headers":[],"relativePath":"guide/crafting.md","filePath":"guide/crafting.md","lastUpdated":1780230058000}'),i={name:"guide/crafting.md"};function l(n,t,h,s,c,g){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="装备制作与精炼指南" tabindex="-1">装备制作与精炼指南 <a class="header-anchor" href="#装备制作与精炼指南" aria-label="Permalink to &quot;装备制作与精炼指南&quot;">​</a></h1><p><img src="'+a+'" alt="RO3 制作系统"></p><h2 id="制作系统" tabindex="-1">制作系统 <a class="header-anchor" href="#制作系统" aria-label="Permalink to &quot;制作系统&quot;">​</a></h2><p>RO3 的装备制作系统由商人转职铁匠后解锁，可以制作各种武器、防具和饰品。</p><h3 id="制作流程" tabindex="-1">制作流程 <a class="header-anchor" href="#制作流程" aria-label="Permalink to &quot;制作流程&quot;">​</a></h3><ol><li><strong>学习配方</strong>：通过技能书或 NPC 学习装备配方</li><li><strong>收集材料</strong>：从怪物掉落、采集、交易所获得材料</li><li><strong>制作装备</strong>：在铁匠铺使用相应技能制作</li><li><strong>成品出售</strong>：制作出的装备可以自用或摆摊出售</li></ol><h3 id="制作等级" tabindex="-1">制作等级 <a class="header-anchor" href="#制作等级" aria-label="Permalink to &quot;制作等级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>等级</th><th>可制作装备</th><th>需求铁匠技能等级</th></tr></thead><tbody><tr><td>初级</td><td>白色品质武器/防具</td><td>1-3 级</td></tr><tr><td>中级</td><td>绿色品质武器/防具</td><td>4-6 级</td></tr><tr><td>高级</td><td>蓝色品质武器/防具</td><td>7-9 级</td></tr><tr><td>大师</td><td>稀有材料转化</td><td>10 级</td></tr></tbody></table><h2 id="精炼系统" tabindex="-1">精炼系统 <a class="header-anchor" href="#精炼系统" aria-label="Permalink to &quot;精炼系统&quot;">​</a></h2><p>精炼是提升装备属性的核心途径，用精炼材料对装备进行强化。</p><h3 id="精炼规则" tabindex="-1">精炼规则 <a class="header-anchor" href="#精炼规则" aria-label="Permalink to &quot;精炼规则&quot;">​</a></h3><ul><li><strong>精炼等级</strong>：+1 到 +15</li><li><strong>精炼材料</strong>：铝（防具）/ 神之金属（武器）</li><li><strong>精炼失败</strong>：+6 以下失败不掉级，+7 以上失败可能掉级或损坏</li></ul><h3 id="精炼概率参考" tabindex="-1">精炼概率参考 <a class="header-anchor" href="#精炼概率参考" aria-label="Permalink to &quot;精炼概率参考&quot;">​</a></h3><table tabindex="0"><thead><tr><th>精炼等级</th><th>成功率（估算）</th></tr></thead><tbody><tr><td>+1 → +4</td><td>100%</td></tr><tr><td>+5 → +6</td><td>约 60%</td></tr><tr><td>+7 → +9</td><td>约 40%</td></tr><tr><td>+10 → +12</td><td>约 20%</td></tr><tr><td>+13 → +15</td><td>约 10%</td></tr></tbody></table><h3 id="精炼技巧" tabindex="-1">精炼技巧 <a class="header-anchor" href="#精炼技巧" aria-label="Permalink to &quot;精炼技巧&quot;">​</a></h3><ul><li><strong>准备多件</strong>：准备 3-5 件同装备轮流精炼</li><li><strong>垫子法</strong>：先用低级装备试概率，感觉&quot;运气好&quot;再上主装备</li><li><strong>保护道具</strong>：高精炼建议使用保护卷轴（防损坏）</li><li><strong>时机选择</strong>：服务器人数少的时段精炼，延迟更低</li></ul><h2 id="属性附魔" tabindex="-1">属性附魔 <a class="header-anchor" href="#属性附魔" aria-label="Permalink to &quot;属性附魔&quot;">​</a></h2><p>部分装备可以通过附魔系统附加额外属性：</p><table tabindex="0"><thead><tr><th>附魔类型</th><th>效果</th><th>适用部位</th></tr></thead><tbody><tr><td>力量附魔</td><td>+STR</td><td>武器/饰品</td></tr><tr><td>敏捷附魔</td><td>+AGI</td><td>武器/披肩</td></tr><tr><td>智力附魔</td><td>+INT</td><td>武器/鞋子</td></tr><tr><td>体质附魔</td><td>+VIT</td><td>铠甲/盾牌</td></tr><tr><td>灵巧附魔</td><td>+DEX</td><td>武器/饰品</td></tr><tr><td>幸运附魔</td><td>+LUK</td><td>饰品</td></tr></tbody></table><h2 id="搬砖推荐" tabindex="-1">搬砖推荐 <a class="header-anchor" href="#搬砖推荐" aria-label="Permalink to &quot;搬砖推荐&quot;">​</a></h2><p>通过制作和精炼系统赚钱是最稳定的收入来源：</p><ol><li><strong>收购低价材料</strong>制作热门装备出售</li><li><strong>接单精炼</strong>：帮其他玩家精炼装备收手续费</li><li><strong>倒卖材料</strong>：低价囤积精炼材料，高价时出手</li></ol>',22)])])}const _=d(i,[["render",l]]);export{p as __pageData,_ as default};
